private var compressionJob: Job? = null
private var timerJob: Job? = null
private var lastSubmissionTimestamp: Long = 0L
private var lastSubmittedComment: String? = null
private var lastSubmittedRating: Int? = null
private var lastSubmittedPhotoIds: List<String> = emptyList()
private var currentBoundDate: String = VnTime.todayString()

init {
    restoreDraft()
    loadData()
    observeSubmitState()
}

fun onForegroundResume() {
    checkAndRefreshDay()
    checkTestTimerOnResume()
}

fun checkAndRefreshDay() {
    val today = VnTime.todayString()
    if (today != currentBoundDate) {
        currentBoundDate = today
        _uiState.update {
            it.copy(
                testStartedAtMs = null,
                minTestDurationRemainingSeconds = 0,
                todayReport = null,
                preparedScreenshots = emptyList(),
                comment = "",
                rating = 5,
            )
        }
        loadData()
        observeSubmitState()
    }
}

private fun checkTestTimerOnResume() {
    val state = _uiState.value
    val startedAt = state.testStartedAtMs ?: return
    val currentBoot = System.currentTimeMillis() - SystemClock.elapsedRealtime()
    val draft = MissionReportDraftStore.loadDraft(appContext, repository.currentUserId().orEmpty(), campaignId, missionId, currentBoundDate)
    if (draft?.bootTimeMs != null && Math.abs(currentBoot - draft.bootTimeMs) > 10_000L) {
        _uiState.update { it.copy(testStartedAtMs = null, minTestDurationRemainingSeconds = 0) }
        return
    }
    val elapsed = SystemClock.elapsedRealtime() - startedAt
    if (elapsed < 10_000L) {
        val remaining = ((10_000L - elapsed + 999) / 1000).toInt()
        _uiState.update { it.copy(minTestDurationRemainingSeconds = remaining) }
        timerJob?.cancel()
        timerJob = viewModelScope.launch {
            for (sec in remaining downTo 0) {
                _uiState.update { it.copy(minTestDurationRemainingSeconds = sec) }
                if (sec > 0) delay(1000L)
            }
        }
    } else {
        _uiState.update { it.copy(minTestDurationRemainingSeconds = 0) }
    }
}

private fun draftKey(userId: String, field: String): String =
    "draft_${userId}_${campaignId}_${missionId}_${VnTime.todayString()}_$field"

private fun restoreDraft() {
    val uid = repository.currentUserId().orEmpty()
    val savedComment = savedStateHandle.get<String>(draftKey(uid, "comment"))
    val savedRating = savedStateHandle.get<Int>(draftKey(uid, "rating"))
    _uiState.update {
        it.copy(
            comment = savedComment ?: it.comment,
            rating = savedRating ?: it.rating,
        )
    }
}

private fun persistDurableDraft() {
    val uid = repository.currentUserId() ?: return
    val state = _uiState.value
    val todayDate = VnTime.todayString()
    val currentBoot = System.currentTimeMillis() - SystemClock.elapsedRealtime()
    val draft = MissionReportDraft(
        userId = uid,
        campaignId = campaignId,
        missionId = missionId,
        reportDate = todayDate,
        rating = state.rating,
        comment = state.comment,
        testStartedAtMs = state.testStartedAtMs,
        bootTimeMs = if (state.testStartedAtMs != null) currentBoot else null,
        preparedImages = state.preparedScreenshots.map {
            DraftAttachment(
                uploadId = it.uploadId,
                filePath = it.file.absolutePath,
                thumbnailPath = it.thumbnailFile?.absolutePath,
                imageHash = it.imageHash,
                sizeBytes = it.sizeBytes,
                contentType = it.contentType,
            )
        }
    )
    MissionReportDraftStore.saveDraft(appContext, draft)
}

